def detect_visual_genre(text: str) -> str | None:
    """Best-matching visual-genre key for a media prompt, or None. Word-boundary keyword match,
    multi-word triggers weighted more."""
    low = str(text or "").lower()
    if not low:
        return None
    best_key: str | None = None
    best_score = 0
    for key, triggers in VISUAL_TRIGGERS.items():
        score = 0
        for kw in triggers:
            if re.search(r"\b" + re.escape(kw) + r"\b", low):
                score += 1 + kw.count(" ")
        if score > best_score:
            best_key, best_score = key, score
    return best_key


# String fields a per-machine overlay may override (see core.craft_overlay / core.craft_upgrade).
_VISUAL_OVERLAY_FIELDS = frozenset(
    {"display_name", "camera_language", "lighting_and_color", "sound_and_voice", "negative_prompt"}
)


def resolve_visual_playbook(genre_key: str | None) -> VisualPlaybook | None:
    """The visual playbook with any per-machine overlay merged over the shipped default (or None)."""
    base = VISUAL_PLAYBOOKS.get(genre_key) if genre_key else None
    if base is None:
        return None
    overlay = craft_overlay.overlay_for("visual_playbooks", genre_key)
    fields = {
        k: v for k, v in overlay.items()
        if k in _VISUAL_OVERLAY_FIELDS and isinstance(v, str) and v.strip()
    }
    return replace(base, **fields) if fields else base


def visual_playbook_directive(genre_key: str | None) -> str:
    """A compact, generation-aware visual-grammar block to fold into the media director prompt.
    Camera + motifs + steering words + genre negative prompt (the highest-leverage fields); the
    full lighting/sound/ingredients live on the VisualPlaybook object and in the doctrine doc."""
    pb = resolve_visual_playbook(genre_key)
    if pb is None:
        return ""
    motifs = "; ".join(pb.visual_motifs[:5])
    vocab = ", ".join(pb.strong_vocabulary[:10])
    return (
        f" Visual grammar for {pb.display_name}. Camera: {pb.camera_language}"
        f" Signature motifs: {motifs}. Steering words: {vocab}."
        f" Negative prompt (always avoid): {pb.negative_prompt}"
    )
